/* ===== Add-on modules (core): router, branch filter, Customer Details, Suppliers, Purchases, Part prices, Expenses, ticket extras ===== */
(function(){
'use strict';
const g=id=>document.getElementById(id);
const num=x=>parseFloat(x)||0;
const role=()=>{ const m=window.curUser&&window.curUser(); return m?m.role:null; };
const isFin=()=>role()!=='sales';
const arr=k=>(DB[k]=DB[k]||[]);
const BR=['DXB','SHJ','AUH'];
const XA=window.XA={views:{},BRF:'',cur:'cd'};
const FIN=['sup','pur','parts','exp','tgt','cash','einv'];
const custs=XA.custs=()=>DB.customers.filter(c=>!XA.BRF||(c.branch||'')===XA.BRF);
const cname=XA.cname=id=>{ const c=custById(id); return c?c.name:'(deleted)'; };
const sname=XA.sname=id=>{ const s=arr('suppliers').find(x=>x.id===id); return s?s.name:'(deleted)'; };
const kpi=XA.kpi=(l,v,s)=>'<div class="card kpi"><span>'+l+'</span><b>'+v+'</b><small>'+(s||'')+'</small></div>';
const kpis=XA.kpis=h=>'<div class="xa-kpis">'+h+'</div>';
const pill=XA.pill=(k,t)=>'<span class="xa-pill '+k+'">'+t+'</span>';
const aed=XA.aed=n=>'AED '+fmtM(n);
const ym=d=>String(d||'').slice(0,7);
const monthsBack=XA.monthsBack=n=>{ const o=[], d=new Date(); d.setDate(1); for(let i=n-1;i>=0;i--){ const x=new Date(d.getFullYear(),d.getMonth()-i,1); o.push(x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')); } return o; };
XA.phone=c=>{ const p=(c.persons||[]).find(x=>x.mobile); let s=String(c.phone||c.tel||(p&&p.mobile)||'').replace(/[^\d]/g,''); if(s.startsWith('00')) s=s.slice(2); if(s.length===10&&s[0]==='0') s='971'+s.slice(1); if(s.length===9&&s[0]==='5') s='971'+s; return s; };
XA.reg=(key,def)=>{ XA.views[key]=def; };
XA.needFin=()=>{ if(isFin()) return true; toast('Only a Manager or Admin can do this.',true); return false; };

const stl=document.createElement('style');
stl.textContent='.xa-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin:0 0 12px}.xa-pill{display:inline-block;padding:2px 9px;border-radius:12px;font-size:.74rem;font-weight:600;background:#eef1f6;color:#33405c}.xa-pill.good{background:#e3f6ea;color:#17703a}.xa-pill.warn{background:#fff3d6;color:#9a6200}.xa-pill.bad{background:#fde4e4;color:#b3261e}'+
'.xa-in{width:100%;padding:6px 8px;border:1px solid #d5dae5;border-radius:6px;font:inherit;background:#fff}.xa-tbl input.xa-in,.xa-tbl select.xa-in{min-width:90px}.xa-bar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:0 0 12px}.xa-bar .sp{margin-left:auto}'+
'.xa-board{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(230px,1fr);gap:10px;overflow-x:auto;padding-bottom:8px}.xa-col{background:#f3f5f9;border-radius:10px;padding:8px;min-height:120px}.xa-col h4{margin:2px 4px 8px;font-size:.85rem;display:flex;justify-content:space-between}.xa-card{background:#fff;border:1px solid #e1e5ee;border-radius:8px;padding:8px 10px;margin-bottom:8px;font-size:.84rem}.xa-card .t{font-weight:700}'+
'.xa-hint{font-size:.78rem;color:#52607d;margin-top:3px}.xa-hint.warn{color:#9a6200}.xa-sig{border:1px dashed #9aa5bd;border-radius:8px;background:#fff;touch-action:none;width:100%;height:110px}.xa-bars{display:flex;align-items:flex-end;gap:6px;height:150px;padding:6px 4px 0;overflow-x:auto}.xa-bars>div{flex:1;min-width:34px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;font-size:.68rem;color:#52607d}.xa-bars i{display:block;width:100%;border-radius:3px 3px 0 0}';
document.head.appendChild(stl);

/* ---------- generic form modal ---------- */
function fm(title,fields,onOk,opt){ opt=opt||{}; let ov=g('xaFm'); if(!ov){ ov=document.createElement('div'); ov.className='overlay'; ov.id='xaFm'; document.body.appendChild(ov); }
  const fld=f=>{ if(f.type==='html') return '<div style="flex:1 1 100%;margin-bottom:8px">'+f.html+'</div>'; const v=f.val==null?'':f.val; let inp; if(f.type==='select') inp='<select class="xa-in" data-k="'+f.k+'">'+f.opts.map(o=>{ const ov_=Array.isArray(o)?o[0]:o, ol=Array.isArray(o)?o[1]:o; return '<option value="'+esc(ov_)+'"'+(String(ov_)===String(v)?' selected':'')+'>'+esc(ol)+'</option>'; }).join('')+'</select>';
    else if(f.type==='textarea') inp='<textarea class="xa-in" rows="'+(f.rows||3)+'" data-k="'+f.k+'" placeholder="'+esc(f.ph||'')+'">'+esc(v)+'</textarea>';
    else inp='<input class="xa-in" data-k="'+f.k+'" type="'+(f.type||'text')+'" '+(f.type==='number'?'step="any" ':'')+'value="'+esc(v)+'" placeholder="'+esc(f.ph||'')+'"'+(f.list?' list="'+f.list+'"':'')+'>';
    return '<div style="margin-bottom:8px;'+(f.half?'flex:1 1 45%;':'')+'"><label style="display:block;font-size:.8rem;margin-bottom:3px">'+esc(f.label)+'</label>'+inp+'</div>'; };
  ov.innerHTML='<div class="modal" style="max-width:'+(opt.w||520)+'px"><h3>'+esc(title)+'</h3>'+(opt.note?'<div class="hint" style="margin:0 0 8px">'+opt.note+'</div>':'')+'<div style="display:flex;flex-wrap:wrap;gap:0 10px">'+fields.map(fld).join('')+'</div><div class="row-end" style="margin-top:12px;display:flex;gap:8px;justify-content:flex-end"><button class="btn ghost" id="xaFmX">'+(opt.cancel||'Cancel')+'</button>'+(opt.noOk?'':'<button class="btn" id="xaFmOk">'+(opt.ok||'Save')+'</button>')+'</div></div>';
  g('xaFmX').onclick=()=>closeModal('xaFm');
  if(!opt.noOk) g('xaFmOk').onclick=()=>{ const o={}; ov.querySelectorAll('[data-k]').forEach(e=>{ o[e.dataset.k]=e.value; }); if(onOk(o)!==false) closeModal('xaFm'); };
  openModal('xaFm'); const f1=ov.querySelector('[data-k]'); if(f1&&!opt.noFocus) try{ f1.focus(); }catch(e){} }
XA.fm=fm;
XA.html=(title,body,w)=>fm(title,[],null,{noOk:true,cancel:'Close',w:w||720,note:body});
XA.print=function(html){ const w=window.open('','_blank'); if(!w){ toast('Allow pop-ups to print.',true); return; } w.document.write('<!doctype html><meta charset="utf-8"><title>Print</title><style>@page{size:A4;margin:14mm}body{font-family:Arial,Helvetica,sans-serif;font-size:12.5px;color:#111}table{border-collapse:collapse;width:100%}th,td{border:1px solid #999;padding:5px 7px;text-align:left}h1,h2{margin:0 0 6px}.hd{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #14213d;padding-bottom:8px;margin-bottom:12px}.hd img{height:48px}.sig{height:70px;border-bottom:1px solid #444;margin-top:30px}.mut{color:#555}</style>'+html); w.document.close(); setTimeout(()=>{ try{ w.focus(); w.print(); }catch(e){} },500); };
XA.coHead=function(title,no){ const co=DB.company||{}; return '<div class="hd"><div>'+(window.LOGO?'<img src="'+LOGO+'"><br>':'')+'<b>'+esc(co.name||'')+'</b><div class="mut">'+esc(co.addr||'')+'<br>'+esc(co.phone||'')+' · '+esc(co.email||'')+(co.trn?'<br>TRN: '+esc(co.trn):'')+'</div></div><div style="text-align:right"><h1>'+esc(title)+'</h1>'+(no?'<b>'+esc(no)+'</b>':'')+'</div></div>'; };

/* ---------- router + nav ---------- */
const nav=[['Customers',[['Customer Details','cd'],['Customer Portal','portal']]],['Contracts',[['Machine Lifecycle','life'],['Toner Alerts','toner']]],['Sales',[['Delivery Notes','dn'],['Targets & Commission','tgt'],['Renewal Pipeline','pipe']]],['Accounts',[['Cash-Flow Forecast','cash'],['Send Reminders','rem'],['e-Invoicing Readiness','einv']]]];
function patchNav(){ if(typeof SD==='undefined'||SD.__xa) return; SD.__xa=1;
  nav.forEach(([grp,items])=>{ const G=SD.find(x=>x.g===grp); if(G) items.forEach(it=>G.items.push([it[0],'xa',it[1]])); });
  const ai=SD.findIndex(x=>x.g==='Accounts'); SD.splice(ai<0?SD.length:ai,0,{g:'Suppliers',i:'🏭',items:[['Supplier Details','xa','sup'],['Purchase Bills','xa','pur'],['Part Price Finder','xa','parts'],['Expenses & P&L','xa','exp']]});
  sdBuild(); roleNav(); try{ sdSync('customers'); }catch(e){} }
function roleNav(){ const sales=role()==='sales'; document.querySelectorAll('#nav .nd a[data-t="xa"]').forEach(a=>{ a.style.display=(sales&&FIN.includes(a.dataset.v))?'none':''; });
  const sel=g('xaBr'); if(sel&&sel.value!==XA.BRF) sel.value=XA.BRF; }
setInterval(roleNav,2500);
const _showTab=window.showTab;
window.showTab=function(t){ if(t==='xa'){ document.querySelectorAll('section[id^="v-"]').forEach(s=>{ s.style.display=s.id==='v-xa'?'':'none'; }); document.querySelectorAll('#nav button').forEach(b=>b.classList.remove('on')); XA.refresh(); try{ sdSync('xa'); }catch(e){} try{ sdClose(); }catch(e){} return; }
  const x=g('v-xa'); if(x) x.style.display='none'; return _showTab.apply(this,arguments); };
const _go=window.go; window.go=function(t,v){ if(t==='xa'){ XA.cur=v||XA.cur; window.showTab('xa'); return; } return _go.apply(this,arguments); };
const _sync=window.sdSync; window.sdSync=function(t,v){ if(t==='xa') v=XA.cur; return _sync.call(this,t,v); };
XA.refresh=function(){ const el=g('v-xa'); if(!el) return; const v=XA.views[XA.cur]; if(!v){ el.innerHTML='<div class="card pad"><div class="empty">Not available.</div></div>'; return; }
  if(FIN.includes(XA.cur)&&!isFin()){ el.innerHTML='<div class="card pad"><div class="empty">This page is only for Managers and Admins.</div></div>'; return; }
  const sc=window.scrollY; try{ el.innerHTML=v.render(); if(v.after) v.after(el); }catch(e){ console.error(e); el.innerHTML='<div class="card pad"><div class="empty">Could not draw this page: '+esc(e.message)+'</div></div>'; } try{ sdSync('xa'); }catch(e){} window.scrollTo(0,sc); };
function mount(){ if(g('v-xa')) return; const s=document.createElement('section'); s.id='v-xa'; s.style.display='none'; const host=g('v-tickets'); host.parentNode.insertBefore(s,host.nextSibling); }
mount();
const live=()=>g('v-xa')&&g('v-xa').style.display!=='none';
XA.save=function(){ save(); if(live()) XA.refresh(); };

/* ---------- branch filter ---------- */
(function(){ const r=document.querySelector('.hdr .right'); if(r&&!g('xaBr')){ const s=document.createElement('select'); s.id='xaBr'; s.title='Branch filter'; s.style.cssText='width:auto;max-width:120px'; s.innerHTML='<option value="">All branches</option>'+BR.map(b=>'<option>'+b+'</option>').join(''); s.onchange=()=>{ XA.BRF=s.value; renderAll(); if(live()) XA.refresh(); toast(XA.BRF?'Showing branch '+XA.BRF+' only (invoice list shows all).':'Showing all branches.'); }; r.insertBefore(s,r.firstChild); }
  ['renderCustomers','renderDash','renderRun','renderProfit','renderCal','ctRender','renderPay'].forEach(n=>{ const f=window[n]; if(typeof f!=='function') return; window[n]=function(){ if(!XA.BRF) return f.apply(this,arguments); const C=DB.customers; DB.customers=C.filter(c=>(c.branch||'')===XA.BRF); try{ return f.apply(this,arguments); } finally{ DB.customers=C; } }; }); })();

/* ---------- Customer Details ---------- */
XA.reg('cd',{render(){ const C=custs(); let h='<div class="sec" style="margin-top:0"><h2>Customer Details</h2></div><div class="hint" style="margin:0 0 8px">Edit the main details in one place. Changes save automatically. Branch drives the branch filter in the header; Sales executive drives targets &amp; commission.</div>';
  const q=(XA.cdq||'').toLowerCase(); h+='<div class="xa-bar"><input class="xa-in" style="max-width:260px" placeholder="Search customer…" value="'+esc(XA.cdq||'')+'" oninput="XA.cdq=this.value;XA.refresh()"><span class="sp"></span><button class="btn" onclick="XA.qaOpen()">⚡ Quick Add Contract + Machines</button> <button class="btn ghost" onclick="openCustomerModal()">+ New Customer</button></div>';
  const rows=C.filter(c=>!q||(c.name+' '+(c.contact||'')+' '+(c.trn||'')+' '+(c.email||'')).toLowerCase().includes(q));
  const inp=(c,f,w,ph)=>'<input class="xa-in" style="min-width:'+(w||110)+'px" value="'+esc(c[f]||'')+'" placeholder="'+(ph||'')+'" onchange="XA.cdSet(\''+c.id+'\',\''+f+'\',this.value)">';
  h+='<div class="card"><div class="tw"><table class="xa-tbl"><thead><tr><th>Customer</th><th>Branch</th><th>Sales executive</th><th>Contact person</th><th>Mobile / WhatsApp</th><th>Email</th><th>TRN</th><th>Terms</th><th>Peppol ID</th><th class="n">Machines</th><th class="n">Balance</th><th></th></tr></thead><tbody>'+(rows.length?rows.map(c=>{ let bal=0; try{ bal=acct(c.id).balance; }catch(e){} return '<tr><td><b>'+esc(c.name)+'</b></td><td><select class="xa-in" style="min-width:80px" onchange="XA.cdSet(\''+c.id+'\',\'branch\',this.value)"><option value="">—</option>'+BR.map(b=>'<option'+(c.branch===b?' selected':'')+'>'+b+'</option>').join('')+'</select></td><td>'+inp(c,'sp',110,'Name')+'</td><td>'+inp(c,'contact',120)+'</td><td>'+inp(c,'tel',120,'+971…')+'</td><td>'+inp(c,'email',150)+'</td><td>'+inp(c,'trn',130,'15 digits')+'</td><td>'+inp(c,'terms',80,'30 days')+'</td><td>'+inp(c,'peppolId',110)+'</td><td class="n">'+(c.machines||[]).length+'</td><td class="n">'+fmtM(bal)+'</td><td><button class="btn sm ghost" onclick="openCustomerModal(\''+c.id+'\')">Full edit</button> <button class="btn sm ghost" title="Merge this duplicate into another customer" onclick="XA.cdMerge(\''+c.id+'\')">⇄ Merge</button></td></tr>'; }).join(''):'<tr><td colspan="12" class="empty">No customers.</td></tr>')+'</tbody></table></div></div>'; return h; }});
XA.cdSet=function(id,f,v){ const c=custById(id); if(!c) return; c[f]=String(v).trim(); save(); if(f==='branch'||f==='sp') toast('Saved.'); };

/* ---------- Suppliers ---------- */
const SUP=()=>arr('suppliers'), PUR=()=>arr('purchases');
const billTotals=b=>{ const sub=(b.rows||[]).reduce((s,r)=>s+num(r.qty)*num(r.rate),0), vat=(b.rows||[]).reduce((s,r)=>s+num(r.qty)*num(r.rate)*num(r.vat)/100,0); return {sub:round2(sub),vat:round2(vat),total:round2(sub+vat)}; };
const paidOf=b=>round2((b.pays||[]).reduce((s,p)=>s+num(p.amt),0));
const supTerms=sid=>{ const s=SUP().find(x=>x.id===sid); const m=s&&String(s.terms||'').match(/\d+/); return m?+m[0]:0; };
XA.reg('sup',{render(){ const P=PUR(); let h='<div class="sec" style="margin-top:0"><h2>Supplier Details</h2><span style="margin-left:auto"><button class="btn" onclick="XA.supEdit()">+ New Supplier</button></span></div>';
  const rows=SUP().slice().sort((a,b)=>a.name.localeCompare(b.name)).map(s=>{ const bl=P.filter(b=>b.sid===s.id), tot=bl.reduce((a,b)=>a+b.total,0), paid=bl.reduce((a,b)=>a+paidOf(b),0); return {s,n:bl.length,tot,paid,due:round2(tot-paid)}; });
  h+=kpis(kpi('Suppliers',rows.length,'')+kpi('Total purchased',aed(rows.reduce((a,r)=>a+r.tot,0)),'all bills')+kpi('Payable now',aed(rows.reduce((a,r)=>a+r.due,0)),'unpaid balance'));
  h+='<div class="card"><div class="tw"><table><thead><tr><th>Supplier</th><th>Contact</th><th>Phone</th><th>Email</th><th>TRN</th><th>Terms</th><th class="n">Bills</th><th class="n">Purchased</th><th class="n">Balance due</th><th></th></tr></thead><tbody>'+(rows.length?rows.map(r=>{ const s=r.s; return '<tr><td><b>'+esc(s.name)+'</b><div class="xa-hint">'+esc(s.notes||'')+'</div></td><td>'+esc(s.contact||'')+'</td><td>'+esc(s.phone||'')+'</td><td>'+esc(s.email||'')+'</td><td>'+esc(s.trn||'')+'</td><td>'+esc(s.terms||'')+'</td><td class="n">'+r.n+'</td><td class="n">'+fmtM(r.tot)+'</td><td class="n"><b>'+fmtM(r.due)+'</b></td><td style="white-space:nowrap"><button class="btn sm ghost" onclick="XA.supEdit(\''+s.id+'\')">✎</button> <button class="btn sm ghost" onclick="XA.supDel(\''+s.id+'\')">🗑</button></td></tr>'; }).join(''):'<tr><td colspan="10" class="empty">No suppliers yet. Add your toner, spare-part and machine suppliers.</td></tr>')+'</tbody></table></div></div>'; return h; }});
XA.supEdit=function(id){ if(!XA.needFin()) return; const s=id?SUP().find(x=>x.id===id):{}; fm(id?'Edit supplier':'New supplier',[{k:'name',label:'Supplier name *',val:s.name},{k:'contact',label:'Contact person',val:s.contact,half:1},{k:'phone',label:'Phone / WhatsApp',val:s.phone,half:1},{k:'email',label:'Email',val:s.email,half:1},{k:'trn',label:'TRN',val:s.trn,half:1},{k:'terms',label:'Payment terms',val:s.terms,ph:'e.g. 30 days',half:1},{k:'addr',label:'Address',val:s.addr,half:1},{k:'notes',label:'Notes (brands supplied, delivery time…)',type:'textarea',val:s.notes}],o=>{ if(!o.name.trim()){ toast('Enter the supplier name.',true); return false; } if(id) Object.assign(s,o); else SUP().push(Object.assign({id:uid()},o)); XA.save(); }); };
XA.supDel=function(id){ if(!XA.needFin()) return; if(PUR().some(b=>b.sid===id)){ toast('This supplier has purchase bills and cannot be deleted.',true); return; } askConfirm('Delete this supplier?',()=>{ DB.suppliers=SUP().filter(x=>x.id!==id); XA.save(); }); };

/* ---------- Part prices (lowest-price suggestion) ---------- */
function priceIdx(){ const m={}; const add=(code,sid,price,date,src,desc)=>{ if(!code||!(price>0)||!sid) return; const k=String(code).trim().toLowerCase(); const a=m[k]=m[k]||{code:String(code).trim(),desc:'',by:{}}; if(desc&&!a.desc) a.desc=desc; const c=a.by[sid]; if(!c||(date||'')>=(c.date||'')) a.by[sid]={sid,price:+price,date:date||'',src}; };
  arr('supPrices').forEach(p=>add(p.code,p.sid,p.price,p.date,'quote',p.desc)); PUR().forEach(b=>(b.rows||[]).forEach(r=>add(r.code,b.sid,r.rate,b.date,'bill',r.desc))); return m; }
const bestFor=XA.bestFor=code=>{ const a=priceIdx()[String(code||'').trim().toLowerCase()]; if(!a) return null; return {code:a.code,desc:a.desc,list:Object.values(a.by).sort((x,y)=>x.price-y.price)}; };
const partDL=()=>'<datalist id="xaPartList">'+Object.values(priceIdx()).map(a=>'<option value="'+esc(a.code)+'">'+esc(a.desc)).join('')+'</datalist>';
function hintHTML(code,sid,rate){ const b=bestFor(code); if(!code||!String(code).trim()) return ''; if(!b) return '<span class="xa-hint">No supplier price on file for this part code yet.</span>'; const low=b.list[0]; let s='🏷 Lowest: <b>'+esc(sname(low.sid))+'</b> '+aed(low.price)+(low.date?' ('+fmtDMY(low.date)+')':''); if(b.list[1]) s+=' · next: '+esc(sname(b.list[1].sid))+' '+aed(b.list[1].price);
  const mine=b.list.find(x=>x.sid===sid); if(sid&&low.sid!==sid&&mine) return '<span class="xa-hint warn">⚠ '+s+' — '+esc(sname(sid))+' is dearer by '+aed(mine.price-low.price)+'</span>'; if(rate>0&&rate>low.price+0.001&&low.sid!==sid) return '<span class="xa-hint warn">⚠ '+s+' — your rate is higher</span>'; return '<span class="xa-hint">'+s+'</span>'; }
XA.reg('parts',{render(){ const idx=Object.values(priceIdx()).sort((a,b)=>a.code.localeCompare(b.code)); let h='<div class="sec" style="margin-top:0"><h2>Part Price Finder</h2><span style="margin-left:auto"><button class="btn" onclick="XA.priceEdit()">+ Add supplier price</button></span></div>'+partDL();
  h+='<div class="card pad"><label style="font-size:.85rem">Type a part code — the cheapest supplier is shown first</label><input id="xaPq" class="xa-in" list="xaPartList" style="max-width:340px;margin-top:4px" placeholder="Part code" value="'+esc(XA.pq||'')+'" oninput="XA.pq=this.value;XA.partShow()"><div id="xaPr" style="margin-top:10px"></div></div>';
  h+='<div class="sec"><h2>All parts</h2></div><div class="card"><div class="tw"><table><thead><tr><th>Part code</th><th>Description</th><th>Lowest supplier</th><th class="n">Lowest price</th><th class="n">Suppliers</th><th>Price date</th></tr></thead><tbody>'+(idx.length?idx.map(a=>{ const l=Object.values(a.by).sort((x,y)=>x.price-y.price); return '<tr style="cursor:pointer" onclick="XA.pq=\''+esc(a.code).replace(/\'/g,'')+'\';XA.refresh()"><td><b>'+esc(a.code)+'</b></td><td>'+esc(a.desc)+'</td><td>'+esc(sname(l[0].sid))+'</td><td class="n">'+fmtM(l[0].price)+'</td><td class="n">'+l.length+'</td><td>'+(l[0].date?fmtDMY(l[0].date):'—')+'</td></tr>'; }).join(''):'<tr><td colspan="6" class="empty">No prices yet. Add a supplier price, or save a purchase bill — prices are learned from bills automatically.</td></tr>')+'</tbody></table></div></div>';
  const pe=arr('supPrices'); if(pe.length) h+='<div class="sec"><h2>Price entries</h2></div><div class="card"><div class="tw"><table><thead><tr><th>Date</th><th>Part code</th><th>Supplier</th><th class="n">Price</th><th>Note</th><th></th></tr></thead><tbody>'+pe.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(p=>'<tr><td>'+fmtDMY(p.date)+'</td><td>'+esc(p.code)+'</td><td>'+esc(sname(p.sid))+'</td><td class="n">'+fmtM(p.price)+'</td><td>'+esc(p.note||'')+'</td><td><button class="btn sm ghost" onclick="XA.priceDel(\''+p.id+'\')">🗑</button></td></tr>').join('')+'</tbody></table></div></div>'; return h; },
  after(){ XA.partShow(); }});
XA.partShow=function(){ const el=g('xaPr'); if(!el) return; const b=bestFor(XA.pq); if(!XA.pq||!String(XA.pq).trim()){ el.innerHTML=''; return; } if(!b){ el.innerHTML='<div class="empty">No supplier has a price for “'+esc(XA.pq)+'” yet.</div>'; return; }
  el.innerHTML='<div style="margin-bottom:6px"><b>'+esc(b.code)+'</b> '+esc(b.desc||'')+'</div><table><thead><tr><th></th><th>Supplier</th><th class="n">Price</th><th>Date</th><th>Source</th><th>vs lowest</th></tr></thead><tbody>'+b.list.map((x,i)=>'<tr><td>'+(i===0?pill('good','Lowest'):'')+'</td><td>'+esc(sname(x.sid))+'</td><td class="n"><b>'+fmtM(x.price)+'</b></td><td>'+(x.date?fmtDMY(x.date):'—')+'</td><td>'+(x.src==='bill'?'Purchase bill':'Quote / price list')+'</td><td>'+(i===0?'—':'+'+fmtM(x.price-b.list[0].price)+' ('+Math.round((x.price/b.list[0].price-1)*100)+'%)')+'</td></tr>').join('')+'</tbody></table>'; };
XA.priceEdit=function(){ if(!XA.needFin()) return; if(!SUP().length){ toast('Add a supplier first.',true); return; } fm('Add supplier price',[{k:'code',label:'Part code *',val:XA.pq||'',list:'xaPartList'},{k:'desc',label:'Description',val:''},{k:'sid',label:'Supplier *',type:'select',opts:SUP().map(s=>[s.id,s.name]),half:1},{k:'price',label:'Price (AED, excl. VAT) *',type:'number',half:1},{k:'date',label:'Price date',type:'date',val:todayISO(),half:1},{k:'note',label:'Note (MOQ, lead time…)',half:1}],o=>{ if(!o.code.trim()||!(num(o.price)>0)){ toast('Enter the part code and a price.',true); return false; } arr('supPrices').push({id:uid(),code:o.code.trim(),desc:o.desc.trim(),sid:o.sid,price:num(o.price),date:o.date||todayISO(),note:o.note.trim()}); XA.pq=o.code.trim(); XA.save(); }); if(!g('xaPartList')){ const d=document.createElement('div'); d.innerHTML=partDL(); document.body.appendChild(d); } };
XA.priceDel=function(id){ if(!XA.needFin()) return; DB.supPrices=arr('supPrices').filter(x=>x.id!==id); XA.save(); };

/* ---------- Purchase bills ---------- */
let pb=null;
XA.reg('pur',{render(){ const P=PUR(), t=todayISO(); const f=XA.pf||{}; let rows=P.slice().sort((a,b)=>b.date.localeCompare(a.date)); if(f.sid) rows=rows.filter(b=>b.sid===f.sid); if(f.st) rows=rows.filter(b=>{ const o=round2(b.total-paidOf(b)); return f.st==='paid'?o<=0:f.st==='overdue'?(o>0&&b.due<t):o>0; });
  const open=P.filter(b=>b.total-paidOf(b)>0.005), od=open.filter(b=>b.due<t);
  let h='<div class="sec" style="margin-top:0;flex-wrap:wrap;gap:8px"><h2>Purchase Bills</h2><span style="margin-left:auto;display:flex;gap:6px;flex-wrap:wrap"><select class="xa-in" style="width:auto" onchange="XA.pf=Object.assign(XA.pf||{},{sid:this.value});XA.refresh()"><option value="">All suppliers</option>'+SUP().map(s=>'<option value="'+s.id+'"'+(f.sid===s.id?' selected':'')+'>'+esc(s.name)+'</option>').join('')+'</select><select class="xa-in" style="width:auto" onchange="XA.pf=Object.assign(XA.pf||{},{st:this.value});XA.refresh()">'+[['','All'],['open','Unpaid'],['overdue','Overdue'],['paid','Paid']].map(o=>'<option value="'+o[0]+'"'+((f.st||'')===o[0]?' selected':'')+'>'+o[1]+'</option>').join('')+'</select><button class="btn" onclick="XA.pbOpen()">+ New Purchase Bill</button></span></div>';
  h+=kpis(kpi('Payable',aed(open.reduce((s,b)=>s+b.total-paidOf(b),0)),open.length+' unpaid bill(s)')+kpi('Overdue',aed(od.reduce((s,b)=>s+b.total-paidOf(b),0)),od.length+' bill(s)')+kpi('Purchased this month',aed(P.filter(b=>ym(b.date)===ym(t)).reduce((s,b)=>s+b.total,0)),''));
  h+='<div class="card"><div class="tw"><table><thead><tr><th>Date</th><th>Bill #</th><th>Supplier inv.</th><th>Supplier</th><th>Due</th><th class="n">Total</th><th class="n">Paid</th><th class="n">Balance</th><th>Status</th><th></th></tr></thead><tbody>'+(rows.length?rows.map(b=>{ const p=paidOf(b), o=round2(b.total-p); return '<tr><td>'+fmtDMY(b.date)+'</td><td><b>'+esc(b.no)+'</b></td><td>'+esc(b.sno||'')+'</td><td>'+esc(sname(b.sid))+'</td><td>'+fmtDMY(b.due)+'</td><td class="n">'+fmtM(b.total)+'</td><td class="n">'+fmtM(p)+'</td><td class="n"><b>'+fmtM(o)+'</b></td><td>'+(o<=0.005?pill('good','Paid'):b.due<t?pill('bad','Overdue'):p>0?pill('warn','Part paid'):pill('','Unpaid'))+'</td><td style="white-space:nowrap">'+(o>0.005?'<button class="btn sm ghost" onclick="XA.pbPay(\''+b.id+'\')">💰 Pay</button> ':'')+'<button class="btn sm ghost" onclick="XA.pbOpen(\''+b.id+'\')">✎</button> <button class="btn sm ghost" onclick="XA.pbDel(\''+b.id+'\')">🗑</button></td></tr>'; }).join(''):'<tr><td colspan="10" class="empty">No purchase bills.</td></tr>')+'</tbody></table></div></div>'; return h; }});
function pbOverlay(){ let ov=g('xaPb'); if(ov) return ov; ov=document.createElement('div'); ov.className='overlay'; ov.id='xaPb'; ov.innerHTML='<div class="modal" style="max-width:1000px;width:96vw"><h3 id="pbT">New purchase bill</h3><div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:8px"><div style="flex:2 1 200px"><label style="font-size:.8rem">Supplier</label><select class="xa-in" id="pb_sid" onchange="XA.pbSup()"></select></div><div style="flex:1 1 130px"><label style="font-size:.8rem">Bill date</label><input class="xa-in" type="date" id="pb_date" onchange="XA.pbSup()"></div><div style="flex:1 1 130px"><label style="font-size:.8rem">Due date</label><input class="xa-in" type="date" id="pb_due"></div><div style="flex:1 1 150px"><label style="font-size:.8rem">Supplier invoice #</label><input class="xa-in" id="pb_sno"></div></div><div class="tw"><table class="xa-tbl"><thead><tr><th style="min-width:130px">Part code</th><th style="min-width:200px">Description</th><th>Qty</th><th>Rate (excl. VAT)</th><th>VAT %</th><th class="n">Amount</th><th></th></tr></thead><tbody id="pbRows"></tbody></table></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:8px;flex-wrap:wrap;gap:8px"><button class="btn ghost sm" onclick="XA.pbAdd()">⊕ Add row</button><div id="pbTot" style="font-weight:700"></div></div><label style="display:inline-flex;gap:6px;align-items:center;margin-top:8px;font-size:.85rem"><input type="checkbox" id="pb_stock" checked> Add the quantities to Stock &amp; Pricing (updates cost price)</label><div class="row-end" style="margin-top:12px;display:flex;gap:8px;justify-content:flex-end"><button class="btn ghost" onclick="closeModal(\'xaPb\')">Cancel</button><button class="btn" onclick="XA.pbSave()">💾 Save bill</button></div></div>'; document.body.appendChild(ov); return ov; }
XA.pbOpen=function(id){ if(!XA.needFin()) return; if(!SUP().length){ toast('Add a supplier first (Suppliers → Supplier Details).',true); return; } pbOverlay(); const b=id?PUR().find(x=>x.id===id):null; pb={id:id||null,rows:b?JSON.parse(JSON.stringify(b.rows)):[{code:'',desc:'',qty:1,rate:0,vat:5}],pays:b?b.pays||[]:[],no:b?b.no:null};
  g('pbT').textContent=b?'Edit purchase bill '+b.no:'New purchase bill'; g('pb_sid').innerHTML=SUP().map(s=>'<option value="'+s.id+'"'+(b&&b.sid===s.id?' selected':'')+'>'+esc(s.name)+'</option>').join(''); g('pb_date').value=b?b.date:todayISO(); g('pb_due').value=b?b.due:addDays(todayISO(),supTerms(g('pb_sid').value)); g('pb_sno').value=b?b.sno||'':''; g('pb_stock').checked=!b; g('pb_stock').parentNode.style.display=b?'none':''; if(!g('xaPartList')){ const d=document.createElement('div'); d.id='xaPartWrap'; document.body.appendChild(d); } const w=g('xaPartWrap'); if(w) w.innerHTML=partDL(); pbDraw(); openModal('xaPb'); };
XA.pbSup=function(){ const d=g('pb_date').value||todayISO(); g('pb_due').value=addDays(d,supTerms(g('pb_sid').value)); pbDraw(); };
function pbDraw(){ g('pbRows').innerHTML=pb.rows.map((r,i)=>'<tr><td><input class="xa-in" list="xaPartList" value="'+esc(r.code)+'" oninput="XA.pbCode('+i+',this)" placeholder="Part code"></td><td><input class="xa-in" id="pbd'+i+'" value="'+esc(r.desc)+'" oninput="XA.pb.rows['+i+'].desc=this.value"><div id="pbh'+i+'">'+hintHTML(r.code,g('pb_sid').value,num(r.rate))+'</div></td><td><input class="xa-in" type="number" step="any" style="min-width:70px" value="'+r.qty+'" oninput="XA.pb.rows['+i+'].qty=num(this.value);XA.pbCalc()"></td><td><input class="xa-in" id="pbr'+i+'" type="number" step="any" style="min-width:90px" value="'+r.rate+'" oninput="XA.pb.rows['+i+'].rate=num(this.value);XA.pbHint('+i+');XA.pbCalc()"></td><td><input class="xa-in" type="number" step="any" style="min-width:60px" value="'+r.vat+'" oninput="XA.pb.rows['+i+'].vat=num(this.value);XA.pbCalc()"></td><td class="n" id="pba'+i+'">'+fmtM(num(r.qty)*num(r.rate)*(1+num(r.vat)/100))+'</td><td><button class="btn sm ghost" onclick="XA.pbDelRow('+i+')">✕</button></td></tr>').join(''); XA.pb=pb; XA.pbCalc(); }
XA.pbCode=function(i,el){ const r=pb.rows[i]; r.code=el.value; const b=bestFor(r.code); if(b){ if(!r.desc&&b.desc){ r.desc=b.desc; g('pbd'+i).value=b.desc; } const mine=b.list.find(x=>x.sid===g('pb_sid').value); if(!(num(r.rate)>0)){ const p=(mine||b.list[0]).price; r.rate=p; g('pbr'+i).value=p; } } XA.pbHint(i); XA.pbCalc(); };
XA.pbHint=function(i){ const r=pb.rows[i], h=g('pbh'+i); if(h) h.innerHTML=hintHTML(r.code,g('pb_sid').value,num(r.rate)); };
XA.pbCalc=function(){ if(!pb) return; pb.rows.forEach((r,i)=>{ const a=g('pba'+i); if(a) a.textContent=fmtM(num(r.qty)*num(r.rate)*(1+num(r.vat)/100)); }); const t=billTotals(pb); g('pbTot').textContent='Sub total '+fmtM(t.sub)+' · VAT '+fmtM(t.vat)+' · Total AED '+fmtM(t.total); };
XA.pbAdd=function(){ pb.rows.push({code:'',desc:'',qty:1,rate:0,vat:5}); pbDraw(); };
XA.pbDelRow=function(i){ pb.rows.splice(i,1); if(!pb.rows.length) pb.rows.push({code:'',desc:'',qty:1,rate:0,vat:5}); pbDraw(); };
XA.pbSave=function(){ const rows=pb.rows.filter(r=>(r.code||r.desc)&&num(r.qty)>0); if(!rows.length){ toast('Add at least one item.',true); return; } const t=billTotals({rows}); const rec={sid:g('pb_sid').value,date:g('pb_date').value||todayISO(),due:g('pb_due').value||g('pb_date').value||todayISO(),sno:g('pb_sno').value.trim(),rows:rows.map(r=>({code:(r.code||'').trim(),desc:(r.desc||'').trim(),qty:num(r.qty),rate:num(r.rate),vat:num(r.vat)})),sub:t.sub,vat:t.vat,total:t.total};
  if(pb.id){ Object.assign(PUR().find(x=>x.id===pb.id),rec); } else { rec.id=uid(); rec.no='PB-'+String(DB.pbSeq=(DB.pbSeq||0)+1).padStart(4,'0'); rec.pays=[]; PUR().push(rec);
    if(g('pb_stock').checked){ rec.rows.forEach(r=>{ const key=(r.desc||r.code).toLowerCase(); let s=DB.stock.find(x=>(x.code&&r.code&&x.code.toLowerCase()===r.code.toLowerCase())||x.item.toLowerCase()===key); if(s){ s.qty=num(s.qty)+r.qty; s.cost=r.rate; } else DB.stock.push({item:r.desc||r.code,code:r.code,qty:r.qty,min:0,cost:r.rate,price:0}); }); } }
  closeModal('xaPb'); XA.save(); toast('Purchase bill saved.'); };
XA.pbDel=function(id){ if(!XA.needFin()) return; askConfirm('Delete this purchase bill? (Stock quantities already added are not reversed.)',()=>{ DB.purchases=PUR().filter(x=>x.id!==id); XA.save(); }); };
XA.pbPay=function(id){ if(!XA.needFin()) return; const b=PUR().find(x=>x.id===id), o=round2(b.total-paidOf(b)); fm('Pay '+sname(b.sid)+' — '+b.no,[{k:'date',label:'Payment date',type:'date',val:todayISO(),half:1},{k:'amt',label:'Amount (AED)',type:'number',val:o,half:1},{k:'method',label:'Method',type:'select',opts:['Bank transfer','Cheque','Cash','Card'],half:1},{k:'ref',label:'Reference',half:1}],v=>{ const a=num(v.amt); if(!(a>0)){ toast('Enter an amount.',true); return false; } (b.pays=b.pays||[]).push({date:v.date,amt:Math.min(a,o),method:v.method,ref:v.ref}); XA.save(); toast('Payment recorded.'); }); };

/* ---------- Expenses & P&L ---------- */
const CATS=['Rent','Salaries','Fuel / transport','Utilities & telecom','Marketing','Spare parts','Toner & consumables','Government fees','Insurance','Other'];
XA.reg('exp',{render(){ const E=arr('expenses'), mo=XA.em||ym(todayISO()); let h='<div class="sec" style="margin-top:0;flex-wrap:wrap;gap:8px"><h2>Expenses &amp; Profit</h2><span style="margin-left:auto;display:flex;gap:6px"><input class="xa-in" type="month" style="width:auto" value="'+mo+'" onchange="XA.em=this.value;XA.refresh()"><button class="btn" onclick="XA.expEdit()">+ Add expense</button></span></div>';
  const rowsM=E.filter(e=>ym(e.date)===mo).sort((a,b)=>b.date.localeCompare(a.date)), tot=rowsM.reduce((s,e)=>s+num(e.amount),0);
  const inc=m=>round2(DB.invoices.filter(v=>ym(v.date)===m&&(!XA.BRF||(custById(v.cid)||{}).branch===XA.BRF)).reduce((s,v)=>s+num(v.sub!=null?v.sub:v.total),0)+DB.sales.filter(s=>ym(s.date)===m&&!s.inv&&(!XA.BRF||(custById(s.cid)||{}).branch===XA.BRF)).reduce((s,x)=>s+num(x.net),0)), pur=m=>round2(PUR().filter(b=>ym(b.date)===m).reduce((s,b)=>s+b.sub,0)), exp=m=>round2(E.filter(e=>ym(e.date)===m).reduce((s,e)=>s+num(e.amount),0));
  const ms=monthsBack(6); h+='<div class="card pad"><b>Profit &amp; loss — last 6 months (excl. VAT)</b><div class="hint" style="margin:2px 0 8px">Income = invoices + sales; Costs = supplier purchase bills + expenses. Lease invoices and sales invoices are both included once.</div><div class="tw"><table><thead><tr><th>Month</th><th class="n">Income</th><th class="n">Purchases</th><th class="n">Expenses</th><th class="n">Net profit</th><th class="n">Margin</th></tr></thead><tbody>'+ms.map(m=>{ const i=inc(m), p=pur(m), x=exp(m), n=round2(i-p-x); return '<tr><td>'+m+'</td><td class="n">'+fmtM(i)+'</td><td class="n">'+fmtM(p)+'</td><td class="n">'+fmtM(x)+'</td><td class="n"><b style="color:'+(n<0?'#b3261e':'#17703a')+'">'+fmtM(n)+'</b></td><td class="n">'+(i>0?Math.round(n/i*100)+'%':'—')+'</td></tr>'; }).join('')+'</tbody></table></div></div>';
  h+='<div class="sec"><h2>Expenses in '+mo+' — '+aed(tot)+'</h2></div><div class="card"><div class="tw"><table><thead><tr><th>Date</th><th>Category</th><th>Description</th><th>Supplier</th><th>Branch</th><th class="n">Amount</th><th class="n">VAT</th><th></th></tr></thead><tbody>'+(rowsM.length?rowsM.map(e=>'<tr><td>'+fmtDMY(e.date)+'</td><td>'+esc(e.cat)+'</td><td>'+esc(e.desc||'')+'</td><td>'+esc(e.sid?sname(e.sid):'')+'</td><td>'+esc(e.branch||'')+'</td><td class="n">'+fmtM(e.amount)+'</td><td class="n">'+fmtM(e.vat||0)+'</td><td style="white-space:nowrap"><button class="btn sm ghost" onclick="XA.expEdit(\''+e.id+'\')">✎</button> <button class="btn sm ghost" onclick="XA.expDel(\''+e.id+'\')">🗑</button></td></tr>').join(''):'<tr><td colspan="8" class="empty">No expenses this month.</td></tr>')+'</tbody></table></div></div>'; return h; }});
XA.expEdit=function(id){ if(!XA.needFin()) return; const e=id?arr('expenses').find(x=>x.id===id):{}; fm(id?'Edit expense':'Add expense',[{k:'date',label:'Date',type:'date',val:e.date||todayISO(),half:1},{k:'cat',label:'Category',type:'select',opts:CATS,val:e.cat,half:1},{k:'desc',label:'Description',val:e.desc},{k:'amount',label:'Amount (AED, excl. VAT)',type:'number',val:e.amount,half:1},{k:'vat',label:'VAT (AED)',type:'number',val:e.vat,half:1},{k:'sid',label:'Supplier (optional)',type:'select',opts:[['','—']].concat(SUP().map(s=>[s.id,s.name])),val:e.sid||'',half:1},{k:'branch',label:'Branch',type:'select',opts:[['','—']].concat(BR),val:e.branch||'',half:1}],o=>{ if(!(num(o.amount)>0)){ toast('Enter the amount.',true); return false; } const r={date:o.date,cat:o.cat,desc:o.desc.trim(),amount:num(o.amount),vat:num(o.vat),sid:o.sid,branch:o.branch}; if(id) Object.assign(e,r); else arr('expenses').push(Object.assign({id:uid()},r)); XA.save(); }); };
XA.expDel=function(id){ if(!XA.needFin()) return; askConfirm('Delete this expense?',()=>{ DB.expenses=arr('expenses').filter(x=>x.id!==id); XA.save(); }); };

/* ---------- Service tickets: SLA + cost ---------- */
const SLA={Urgent:24,High:48,Normal:120,Low:240};
(function(){ const f=window.renderTickets; if(typeof f!=='function') return; window.renderTickets=function(){ f.apply(this,arguments); try{ const el=g('tkTable'); if(!el) return; const T=arr('tickets'), now=Date.now(); let late=0;
  el.querySelectorAll('tbody tr').forEach(tr=>{ const no=tr.cells[0]&&tr.cells[0].textContent.trim(), t=T.find(x=>x.no===no); if(!t) return; const open=['Open','In progress'].includes(t.st), hrs=(now-new Date(t.date+'T08:00:00').getTime())/36e5, breach=open&&hrs>(SLA[t.pri]||120); if(breach){ late++; tr.cells[0].insertAdjacentHTML('beforeend',' <span title="Past SLA ('+(SLA[t.pri]||120)+'h for '+esc(t.pri)+')" style="color:#b3261e;font-size:.75rem">⏰ SLA</span>'); } const last=tr.cells[tr.cells.length-1]; last.insertAdjacentHTML('beforeend',' <button class="btn sm ghost" title="Parts / labour cost of this ticket" onclick="XA.tkCost(\''+t.id+'\')">💲'+(t.cost?fmtM(t.cost):'Cost')+'</button>'); });
  let b=g('xaTkSla'); if(!b){ b=document.createElement('div'); b.id='xaTkSla'; b.style.cssText='margin:0 0 8px;font-size:.88rem'; el.parentNode.insertBefore(b,el); } const tot=T.reduce((s,t)=>s+num(t.cost),0); b.innerHTML=(late?'<b style="color:#b3261e">⏰ '+late+' open ticket(s) are past their target response time</b> (Urgent 24h · High 48h · Normal 5 days · Low 10 days). ':'<span style="color:#17703a">✔ No open ticket is past its target response time.</span> ')+(tot?' · Total ticket cost logged: <b>'+aed(tot)+'</b>':''); }catch(e){ console.warn(e); } }; })();
XA.tkCost=function(id){ const t=arr('tickets').find(x=>x.id===id); if(!t) return; fm('Cost of ticket '+t.no,[{k:'cost',label:'Parts + labour cost (AED)',type:'number',val:t.cost||''}],o=>{ t.cost=num(o.cost); save(); if(window.renderTickets) renderTickets(); toast('Cost saved — it now counts in Machine Lifecycle.'); }); };


/* ---------- Quick Add Contract: customer + contract + ALL machines in one step ---------- */
const pdate=x=>{ x=String(x||'').trim(); if(!x) return ''; let m=x.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/); if(m) return m[1]+'-'+m[2].padStart(2,'0')+'-'+m[3].padStart(2,'0'); m=x.match(/^(\d{1,2})[-./](\d{1,2})[-./](\d{2}|\d{4})$/); if(!m) return null; const y=m[3].length===2?'20'+m[3]:m[3]; return y+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0'); };
XA.qaR=[];
const qaModels=()=>{ const set=new Set(); Object.values(DB.models||{}).forEach(a=>(a||[]).forEach(m=>set.add(m))); DB.customers.forEach(c=>c.machines.forEach(m=>{ if(m.model) set.add(m.model); })); return [...set].sort((a,b)=>a.localeCompare(b)); };
XA.qaDraw=function(){ const tb=g('qaBody'); if(!tb) return; tb.innerHTML=XA.qaR.map((r,i)=>'<tr><td style="text-align:center;width:40px">'+(i+1)+'</td><td><input class="xa-in" list="xaDeptList" style="min-width:130px" value="'+esc(r.dept)+'" placeholder="Department" oninput="XA.qaR['+i+'].dept=this.value" onpaste="XA.qaPaste(event,'+i+',0)"></td><td><input class="xa-in" list="xaModelList" style="min-width:170px" value="'+esc(r.model)+'" placeholder="Type to search model…" oninput="XA.qaR['+i+'].model=this.value" onpaste="XA.qaPaste(event,'+i+',1)"></td><td><input class="xa-in" style="min-width:130px" value="'+esc(r.serial)+'" oninput="XA.qaR['+i+'].serial=this.value" onpaste="XA.qaPaste(event,'+i+',2)"></td><td><input class="xa-in" style="min-width:140px" value="'+esc(r.eqid)+'" oninput="XA.qaR['+i+'].eqid=this.value" onpaste="XA.qaPaste(event,'+i+',3)"></td><td><input class="xa-in" style="min-width:110px" value="'+esc(r.start)+'" placeholder="dd-mm-yyyy" oninput="XA.qaR['+i+'].start=this.value" onpaste="XA.qaPaste(event,'+i+',4)"></td><td><button class="btn sm ghost" onclick="XA.qaDel('+i+')">✕</button></td></tr>').join(''); const n=g('qaCount'); if(n) n.textContent=XA.qaR.filter(r=>r.model||r.serial||r.eqid).length; };
XA.qaAdd=function(n){ for(let i=0;i<(n||1);i++){ const last=XA.qaR[XA.qaR.length-1]; XA.qaR.push({dept:last?last.dept:'',model:last?last.model:'',serial:'',eqid:'',start:''}); } XA.qaDraw(); };
XA.qaDel=function(i){ XA.qaR.splice(i,1); if(!XA.qaR.length) XA.qaR.push({dept:'',model:'',serial:'',eqid:'',start:''}); XA.qaDraw(); };
XA.qaFill=function(){ const m=(XA.qaR.find(r=>r.model)||{}).model||'', d=(XA.qaR.find(r=>r.dept)||{}).dept||''; XA.qaR.forEach(r=>{ r.model=m; if(d) r.dept=d; }); XA.qaDraw(); };
XA.qaPaste=function(e,row,col){ const t=(e.clipboardData||window.clipboardData).getData('text'); if(!/[\t\n]/.test(t.trim())) return; e.preventDefault(); const lines=t.replace(/\r/g,'').split('\n').filter(l=>l.trim()!==''); const keys=['dept','model','serial','eqid','start'];
  lines.forEach((l,li)=>{ const cells=l.split('\t'); const r=row+li; while(XA.qaR.length<=r) XA.qaR.push({dept:'',model:'',serial:'',eqid:'',start:''}); cells.forEach((v,ci)=>{ if(col+ci<5) XA.qaR[r][keys[col+ci]]=v.trim(); }); }); XA.qaDraw(); toast(lines.length+' row(s) pasted.'); };
XA.qaOpen=function(cid){ if(!XA.needFin()) return; const cs=DB.customers; XA.qaR=[{dept:'',model:'',serial:'',eqid:'',start:''},{dept:'',model:'',serial:'',eqid:'',start:''}];
  let dl=g('xaModelList'); if(!dl){ dl=document.createElement('datalist'); dl.id='xaModelList'; document.body.appendChild(dl); } dl.innerHTML=qaModels().map(m=>'<option value="'+esc(m)+'">').join(''); let dd=g('xaDeptList'); if(!dd){ dd=document.createElement('datalist'); dd.id='xaDeptList'; document.body.appendChild(dd); } dd.innerHTML=[...new Set(DB.customers.flatMap(c=>c.machines.map(m=>m.department)).filter(Boolean))].sort().map(m=>'<option value="'+esc(m)+'">').join('');
  const grid='<div style="font-weight:600;font-size:.85rem;margin:4px 0">Machines <span class="xa-hint">(<b id="qaCount">0</b> filled)</span></div><div class="tw"><table class="xa-tbl"><thead><tr><th>Sr.#</th><th>Department</th><th>Machine model</th><th>Serial no.</th><th>Equipment ID</th><th>Start date <span class="xa-hint">(optional)</span></th><th></th></tr></thead><tbody id="qaBody"></tbody></table></div><div class="xa-bar" style="margin-top:6px"><button class="btn sm ghost" type="button" onclick="XA.qaAdd(1)">⊕ Add row</button><button class="btn sm ghost" type="button" onclick="XA.qaAdd(5)">⊕ Add 5 rows</button><button class="btn sm ghost" type="button" onclick="XA.qaFill()">⬇ Same department &amp; model for all rows</button><span class="xa-hint">Tip: copy rows from Excel (Department · Model · Serial · Equip ID · Start date) and paste into the first cell — the grid fills itself.</span></div>';
  fm('⚡ Quick Add Contract + Machines',[
   {k:'cid',label:'Customer',type:'select',opts:[['','➕ New customer (type name below)']].concat(cs.map(c=>[c.id,c.name])),val:cid||''},
   {k:'cname',label:'New customer name (only if “New customer” chosen)',ph:'e.g. Ajman Chamber of Commerce and Industry'},
   {k:'ref',label:'Contract no.',ph:'MT/LC-756/26',half:1},{k:'type',label:'Contract type',type:'select',opts:['Lease','AMC','Rental'],half:1},
   {k:'start',label:'Contract start',type:'date',half:1},{k:'end',label:'Contract end (blank = 1 year)',type:'date',half:1},
   {k:'desc',label:'Invoice wording',ph:'Kyocera Multifunctional A3 Colour Printer'},
   {k:'rate',label:'Lease per machine per month (AED)',type:'number',ph:'450',half:1},{k:'cycle',label:'Lease billed',type:'select',opts:['Quarterly','Monthly','Yearly'],half:1},
   {k:'xcycle',label:'Extra copies billed',type:'select',opts:['Monthly','Quarterly','Yearly'],half:1},{k:'one',label:'Invoice layout',type:'select',opts:[['1','ONE line for all machines (7 units × months)'],['0','Standard (grouped by rate)']],half:1},
   {k:'fm',label:'Free mono copies / machine / month',type:'number',ph:'2500',half:1},{k:'fc',label:'Free colour copies / machine / month',type:'number',ph:'2500',half:1},
   {k:'rm',label:'Extra mono rate (AED / copy)',type:'number',ph:'0.035',half:1},{k:'rc',label:'Extra colour rate (AED / copy)',type:'number',ph:'0.18',half:1},
   {k:'_g',type:'html',html:grid}
  ],o=>{
   if(!o.cid&&!o.cname.trim()){ toast('Choose a customer or type the new customer name.',true); return false; }
   if(!(num(o.rate)>0)){ toast('Enter the lease amount per machine per month.',true); return false; }
   const st=pdate(o.start); if(st===null){ toast('Contract start date is not valid.',true); return false; }
   const rows=[]; let bad='';
   XA.qaR.forEach((r,i)=>{ if(!(r.model||r.serial||r.eqid||r.start).toString().trim()) return; const sd=pdate(r.start); if(sd===null) bad=bad||('row '+(i+1)+' start date'); if(!String(r.model).trim()) bad=bad||('row '+(i+1)+' machine model'); rows.push({dept:String(r.dept||'').trim(),model:String(r.model).trim(),serial:String(r.serial).trim(),eqid:String(r.eqid).trim(),start:sd||''}); });
   if(bad){ toast('Please check '+bad+'.',true); return false; } if(!rows.length){ toast('Add at least one machine row.',true); return false; }
   const have=new Set(); DB.customers.forEach(c=>c.machines.forEach(m=>{ if(m.serial) have.add(m.serial.toLowerCase()); })); const dup=rows.filter(r=>r.serial&&have.has(r.serial.toLowerCase())); const seen=new Set(); const dupIn=rows.filter(r=>{ const k=r.serial.toLowerCase(); if(!k) return false; if(seen.has(k)) return true; seen.add(k); return false; });
   if(dup.length||dupIn.length){ toast('Serial already exists: '+(dup.concat(dupIn)).map(r=>r.serial).slice(0,4).join(', ')+' — fix or remove it.',true); return false; }
   let c=o.cid?custById(o.cid):null; if(!c){ const k0=Object.assign(kBase(),{id:newKid()}); c={id:uid(),name:o.cname.trim(),machines:[],monthlyLease:0,leaseCycle:'Monthly',excessCycle:'Quarterly',leaseFrom:'',leaseTo:'',excessFrom:'',excessTo:'',freeMono:0,freeColor:0,rateMono:0,rateColor:0,contracts:[k0],contract:k0}; DB.customers.push(c); }
   const end=o.end||(st?plusYear(st):''); let k=c.contracts.find(x=>!x.end&&!x.ref&&!c.machines.some(m=>m.contractId===x.id)); if(!k){ k=Object.assign(kBase(),{id:newKid()}); c.contracts.push(k); }
   Object.assign(k,{ref:o.ref.trim()||(c.name+' Contract'),type:o.type,start:st||'',end:end,oneLine:o.one==='1'});
   rows.forEach(r=>{ c.machines.push({id:uid(),contractId:k.id,type:'Printer',status:'Active',department:r.dept,model:r.model,serial:r.serial,eqid:r.eqid,desc:o.desc.trim(),remarks:r.start&&r.start!==st?'Lease starts '+fmtDMY(r.start):'',start:r.start||st||'',a3Factor:2,plotUnit:'sqm',freeBasis:'period',freeMono:num(o.fm),freeColor:num(o.fc),rateMono:num(o.rm),rateColor:num(o.rc),freePlot:0,ratePlot:0,rateA0:0,rateA1:0,rateA2:0,readings:[],events:[],
     monthlyLease:num(o.rate),billM:true,billQ:false,billY:false,priceQ:0,priceY:0,leaseCycle:o.cycle,excessCycle:o.xcycle,leaseFrom:'',leaseTo:'',excessFrom:'',excessTo:''}); addModel({model:r.model,brand:r.model.split(' ')[0]}); });
   c.contract=c.contracts[0]; try{ normalizeData(); }catch(e){} save(); renderAll(); if(live()) XA.refresh();
   toast(rows.length+' machine(s) added to '+c.name+' — contract '+k.ref+'. Now do the Reading Run, then Invoices.'); }, {ok:'Create contract + machines',w:860,noFocus:true,note:'Fill this once. Every machine gets the same rate, free copies and invoice wording; model, serial, equipment ID and start date are per machine.'}); XA.qaDraw(); };
(function(){ const r=document.querySelector('.hdr .right'); if(r&&!g('xaQa')){ const b=document.createElement('button'); b.id='xaQa'; b.className='btn sm'; b.textContent='⚡ Quick Add'; b.title='Add a customer contract with all its machines in one step'; b.onclick=()=>XA.qaOpen(); r.insertBefore(b,r.firstChild); } })();

/* ---------- Excel import gate: ask WHICH customer, and warn about changes before anything is written ---------- */
const STOPW=new Set(['lease','calculation','calculations','contract','period','the','and','llc','sheet','copy','final','new','data','for']);
const toks=x=>String(x||'').toLowerCase().replace(/[^a-z0-9\u0600-\u06ff ]+/g,' ').split(/\s+/).filter(w=>w.length>=3&&!STOPW.has(w)&&!/^\d+$/.test(w));
const bestCust=name=>{ const t=toks(name); let b=null,bs=0; DB.customers.forEach(c=>{ const u=new Set(toks(c.name)), sh=t.filter(w=>u.has(w)).length, sc=sh/Math.max(1,t.length,u.size); if(sh>0&&sc>bs){ bs=sc; b=c; } }); return b; };
function impGroups(wb,fname){ const out=[]; if(wb.Sheets['Customers']){ const sh=n=>wb.Sheets[n]?XLSX.utils.sheet_to_json(wb.Sheets[n],{defval:''}):[]; const names=[]; ['Customers','Machines','Readings','Ledger'].forEach(n=>sh(n).forEach(r=>{ const v=String(r['Customer Name']||'').trim(); if(v&&!names.includes(v)) names.push(v); }));
    names.forEach(n=>out.push({name:n,raw:false,rows:sh('Machines').filter(r=>String(r['Customer Name']||'').trim()===n).map((r,i)=>({sr:String(i+1),dept:String(r['Department']||'').trim(),model:String(r['Model']||'').trim(),serial:String(r['Serial Number']||'').trim(),eqid:String(r['Equipment ID']||'').trim()}))})); }
  else { const rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,raw:true}); const hr=rows.find(r=>r&&r.some(v=>String(v||'').trim()==='Sno'))||rows[0], hi=rows.indexOf(hr); let ds=hi+2; while(ds<rows.length&&!(rows[ds]&&rows[ds][0])) ds++; const list=[]; for(let r=ds;r<rows.length;r++){ const row=rows[r]; if(!row||!row[0]) continue; list.push({sr:String(row[0]).trim(),dept:String(row[1]||'').trim(),model:String(row[2]||'').trim(),serial:String(row[3]||'').trim(),eqid:String(row[4]||'').trim()}); } out.push({name:cleanNameFromFile(fname),raw:true,rows:list}); }
  return out; }
function impDiff(G,cid){ const c=cid?custById(cid):null, d={match:0,add:[],chg:[]}; G.rows.forEach(r=>{ const key=r.serial.toLowerCase(); const m=c&&key?c.machines.find(x=>(x.serial||'').toLowerCase()===key):null; if(!m){ d.add.push(r); return; } d.match++; const pos=c.machines.indexOf(m)+1;
    [['Department',m.department,r.dept],['Machine model',m.model,r.model],['Equipment ID',m.eqid,r.eqid]].forEach(([f,a,b])=>{ if(String(a||'').trim()!==String(b||'').trim()&&String(b||'').trim()!=='') d.chg.push({serial:r.serial,f,a:a||'—',b}); }); if(String(pos)!==String(r.sr)&&/^\d+$/.test(String(r.sr))) d.chg.push({serial:r.serial,f:'Sr.#',a:pos,b:r.sr}); }); return d; }
XA.importGate=function(wb,fname,go){ let groups; try{ groups=impGroups(wb,fname); }catch(e){ go(); return; } if(!groups.length){ go(); return; }
  const opts=[['','➕ Create as a NEW customer']].concat(DB.customers.map(c=>[c.id,c.name])), pre=groups.map(G=>{ const ex=DB.customers.find(c=>c.name.trim().toLowerCase()===G.name.trim().toLowerCase()), b=ex||bestCust(G.name); return b?b.id:''; });
  let html='<div class="hint" style="margin-bottom:8px">Choose which customer each file name belongs to. Nothing is written until you press Import.</div>'+groups.map((G,i)=>'<div class="card pad" style="margin-bottom:10px"><div><b>'+esc(G.name)+'</b> <span class="xa-hint">('+G.rows.length+' machine row(s) in file)</span></div><label style="font-size:.8rem;display:block;margin:6px 0 3px">Add this data to</label><select class="xa-in" data-k="map'+i+'" onchange="XA.impShow('+i+')">'+opts.map(o=>'<option value="'+esc(o[0])+'"'+(o[0]===pre[i]?' selected':'')+'>'+esc(o[1])+'</option>').join('')+'</select><div id="impN'+i+'" style="margin-top:6px"><input class="xa-in" data-k="new'+i+'" value="'+esc(G.name)+'" placeholder="New customer name"></div><div id="impd'+i+'" style="margin-top:8px"></div></div>').join('')+'<label style="font-size:.8rem;display:block;margin:6px 0 3px">If Sr.#, department, model or equipment ID differ from what is saved</label><select class="xa-in" data-k="mode"><option value="update">Update my records with the values in the file</option><option value="keep">Keep my current values (only add new machines / readings)</option></select>';
  XA.impShow=function(i){ const el=g('xaFm'); const v=el.querySelector('[data-k="map'+i+'"]').value, G=groups[i]; g('impN'+i).style.display=v?'none':''; const d=v?impDiff(G,v):{match:0,add:G.rows,chg:[]}; let h='<div class="xa-hint">'+(v?'Matched machines: <b>'+d.match+'</b> · New machines to add: <b>'+d.add.length+'</b> · ':'New customer · ')+(d.chg.length?'<b style="color:#b3261e">⚠ '+d.chg.length+' difference(s) found</b>':'no differences')+'</div>';
    if(d.chg.length) h+='<div class="tw" style="max-height:170px;overflow:auto;margin-top:6px"><table><thead><tr><th>Serial</th><th>Field</th><th>Saved now</th><th>In file</th></tr></thead><tbody>'+d.chg.slice(0,60).map(x=>'<tr><td>'+esc(x.serial)+'</td><td>'+x.f+'</td><td>'+esc(x.a)+'</td><td><b>'+esc(x.b)+'</b></td></tr>').join('')+'</tbody></table></div>'; g('impd'+i).innerHTML=h; };
  fm('Import — which customer?',[{k:'_g',type:'html',html:html}],o=>{ const mode=o.mode||'update'; const map=groups.map((G,i)=>({G,cid:o['map'+i]||'',nn:(o['new'+i]||G.name).trim()})); if(map.some(m=>!m.cid&&!m.nn)){ toast('Type the new customer name.',true); return false; }
    const snap={}; map.forEach(m=>{ if(m.cid) custById(m.cid).machines.forEach(x=>{ if(x.serial) snap[m.cid+'|'+x.serial.toLowerCase()]={m:x,department:x.department,model:x.model,eqid:x.eqid}; }); });
    const target=m=>m.cid?custById(m.cid).name:m.nn;
    if(groups[0].raw){ XA.impName=target(map[0]); } else { map.forEach(m=>{ const to=target(m); ['Customers','Machines','Readings','Ledger'].forEach(n=>{ const ws=wb.Sheets[n]; if(!ws||!ws['!ref']) return; const rg=XLSX.utils.decode_range(ws['!ref']); let col=-1; for(let c=rg.s.c;c<=rg.e.c;c++){ const h=ws[XLSX.utils.encode_cell({r:rg.s.r,c})]; if(h&&String(h.v).trim()==='Customer Name') col=c; } if(col<0) return; for(let r=rg.s.r+1;r<=rg.e.r;r++){ const a=XLSX.utils.encode_cell({r,c:col}), cell=ws[a]; if(cell&&String(cell.v).trim()===m.G.name){ cell.v=to; cell.t='s'; delete cell.w; } } }); }); }
    try{ go(); } finally { XA.impName=''; }
    if(mode==='keep') Object.values(snap).forEach(sn=>{ sn.m.department=sn.department; sn.m.model=sn.model; sn.m.eqid=sn.eqid; });
    try{ normalizeData(); }catch(e){} save(); renderAll(); if(live()) XA.refresh(); toast('Import finished'+(mode==='keep'?' — your existing department/model/IDs were kept.':'.')); },{ok:'Import',w:760,noFocus:true}); groups.forEach((G,i)=>XA.impShow(i)); };
(function(){ const c=window.cleanNameFromFile; if(typeof c==='function') window.cleanNameFromFile=function(f){ return XA.impName||c(f); }; })();

/* ---------- Merge a duplicate customer into another ---------- */
XA.cdMerge=function(fromId){ if(!XA.needFin()) return; const A=custById(fromId); if(!A) return; const others=DB.customers.filter(c=>c.id!==fromId); if(!others.length){ toast('There is no other customer to merge into.',true); return; }
  const cnt=k=>arr(k).filter(x=>x.cid===fromId).length, guess=bestCust(A.name); fm('Merge “'+A.name+'” into…',[{k:'to',label:'Keep this customer',type:'select',opts:others.map(c=>[c.id,c.name]),val:guess&&guess.id!==fromId?guess.id:others[0].id}],o=>{ const B=custById(o.to); if(!B) return false;
    let moved=0,joined=0; const find=sn=>sn&&B.machines.find(x=>x.serial&&x.serial.toLowerCase()===sn.toLowerCase()); if(!B.contracts||!B.contracts.length){ const k0=Object.assign(kBase(),{id:newKid()}); B.contracts=[k0]; B.contract=k0; }
    A.machines.forEach(m=>{ const t=find(m.serial); if(t){ (m.readings||[]).forEach(r=>{ if(!t.readings.some(x=>x.month===r.month)) t.readings.push(r); }); t.readings.sort((a,b)=>a.month.localeCompare(b.month)); (m.events||[]).forEach(e=>t.events.push(e)); ['department','eqid','model','desc'].forEach(f=>{ if(!t[f]&&m[f]) t[f]=m[f]; }); joined++; }
      else { const k=(A.contracts||[]).find(x=>x.id===m.contractId); if(k&&(k.ref||k.end)){ if(!B.contracts.some(x=>x.id===k.id)) B.contracts.push(k); } else m.contractId=B.contracts[0].id; B.machines.push(m); moved++; } });
    ['invoices','ledger','sales','quotes','tickets','dnotes'].forEach(k=>arr(k).forEach(x=>{ if(x.cid===fromId) x.cid=o.to; })); DB.customers=DB.customers.filter(c=>c.id!==fromId);
    try{ normalizeData(); }catch(e){} save(); renderAll(); XA.refresh(); toast('Merged: '+joined+' machine(s) matched by serial, '+moved+' moved. “'+A.name+'” removed.'); },{ok:'Merge & remove duplicate',note:'Machines with the same serial number are combined (readings are kept). Invoices, payments, tickets and delivery notes move to the customer you keep. “'+esc(A.name)+'” has '+A.machines.length+' machine(s), '+cnt('invoices')+' invoice(s).'}); };

setTimeout(patchNav,0);
document.addEventListener('DOMContentLoaded',()=>{});
window.XA_ready=true;
})();
